imageHint: "Skokloster Castle Baroque architecture",
    descriptionAdvanced: {
      de: "Das Schloss Skokloster, gelegen am Mälaren-See zwischen Stockholm und Uppsala, gilt als eines der bedeutendsten Barockmuseen der Welt. Es wurde zwischen 1654 und 1676 für den schwedischen Feldherrn und Reichsadmiral Carl Gustaf Wrangel nach Entwürfen von Caspar Vogel errichtet. Trotz seiner prachtvollen Architektur blieb der Bau nach Wrangels Tod unvollendet, was besonders im großen Festsaal sichtbar ist, der noch heute im Zustand einer Baustelle des 17. Jahrhunderts verharrt. Das Schloss beherbergt eine außergewöhnliche Sammlung von Kunstwerken, Möbeln, Textilien und Waffen aus der Zeit des Dreißigjährigen Krieges. Da das Gebäude nie modernisiert wurde und keine Heizung besitzt, sind die Innenräume und Inventare in einem authentischen Zustand erhalten geblieben. Heute ist Skokloster ein staatliches Museum und Teil des schwedischen Kulturerbes, das jährlich zahlreiche Besucher durch seine unberührte historische Atmosphäre anzieht.",
      hu: "A Skokloster-kastély a Mälaren-tó partján, Stockholm és Uppsala között helyezkedik el, és a világ egyik legjelentősebb barokk emlékműveként tartják számon. A kastélyt 1654 és 1676 között építtette Carl Gustaf Wrangel gróf, a svéd hadsereg tábornagya és birodalmi admirálisa, Caspar Vogel tervei alapján. Érdekessége, hogy Wrangel 1676-ban bekövetkezett halála után az építkezés hirtelen leállt, így a hatalmas lakomaterem a mai napig befejezetlen állapotban, korabeli állványzatokkal és szerszámokkal látható. A kastély falai között egyedülálló művészeti, bútor-, textil- és fegyvergyűjtemény található, amely a harmincéves háború korszakának gazdagságát tükrözi. Mivel az épületet soha nem modernizálták és fűtési rendszerrel sem látták el, a belső terek szinte érintetlenül maradtak meg a 17. századból. Napjainkban állami múzeumként működik, bemutatva Svédország nagyhatalmi korszakának kulturális és katonai örökségét.",
      ro: "Castelul Skokloster, situat pe malul lacului Mälaren între Stockholm și Uppsala, este considerat unul dintre cele mai importante muzee baroce din lume. Edificiul a fost construit între 1654 și 1676 pentru contele Carl Gustaf Wrangel, mare amiral și mareșal suedez, după planurile arhitectului Caspar Vogel. O particularitate remarcabilă a castelului este faptul că lucrările au fost întrerupte brusc la moartea lui Wrangel, lăsând marea sală de banchete nefinalizată, păstrând și astăzi schelele și uneltele de construcție din secolul al XVII-lea. Castelul adăpostește colecții impresionante de artă, mobilier, textile și o celebră armurărie, martore ale bogăției Suediei din perioada Războiului de Treizeci de Ani. Deoarece clădirea nu a fost niciodată modernizată sau dotată cu încălzire centrală, interioarele s-au conservat într-o stare de autenticitate rară. Astăzi, Skokloster este un muzeu de stat care oferă o incursiune fascinantă în viața nobiliară și cultura barocă suedeză.",
      en: "Skokloster Castle, situated on the shores of Lake Mälaren between Stockholm and Uppsala, is widely regarded as one of the world's premier Baroque museums. Constructed between 1654 and 1676 for Count Carl Gustaf Wrangel, a prominent Swedish military commander and statesman, the castle was designed by architect Caspar Vogel. A unique aspect of the structure is the unfinished banquet hall, which remains exactly as it was when construction halted following Wrangel's death in 1676, complete with original 17th-century scaffolding. The castle houses an extraordinary collection of art, furniture, textiles, and a vast armory, reflecting the wealth and power of the Swedish Empire during the 17th century. Because the building was never modernized or equipped with central heating, the interiors have been exceptionally preserved in their original state. Today, Skokloster operates as a national museum, offering visitors an authentic window into the life and tastes of the Swedish nobility during the Baroque era.",
      es: "El castillo de Skokloster es uno de los castillos barrocos mejor conservados de Europa. Fue construido en el siglo XVII para el conde Carl Gustaf Wrangel y quedó parcialmente inacabado.",
      pt: "O Castelo de Skokloster é um dos castelos barrocos mais bem preservados da Europa. Foi construído no século XVII para o Conde Carl Gustaf Wrangel e permaneceu parcialmente inacabado.",
      fr: "Le château de Skokloster est l'un des châteaux baroques les mieux conservés d'Europe. Il a été construit au XVIIe siècle pour le comte Carl Gustaf Wrangel et est resté partiellement inachevé.",
    },
    factsAdvanced: {
      de: ["Das Schloss wurde zwischen 1654 und 1676 erbaut.", "Der große Festsaal ist seit dem Tod Wrangels im Jahr 1676 unvollendet.", "Die Waffensammlung umfasst über 1.000 Exponate aus dem 17. Jahrhundert.", "Es gehört zu den am besten erhaltenen Barockgebäuden Europas.", "Das Schloss verfügt über keine moderne Heizung oder Elektrizität in den Prunkräumen.", "Es wurde 1967 vom schwedischen Staat für 25 Millionen Kronen gekauft."],
      hu: ["A kastély építése 1654-ben kezdődött és 1676-ig tartott.", "A nagy lakomaterem 1676 óta befejezetlen, korabeli szerszámokkal.", "A könyvtár több mint 30 000 kötetet és ritka kéziratot őriz.", "A fegyvertár a világ egyik legnagyobb 17. századi magángyűjteménye.", "A kastély 1967-ben került a svéd állam tulajdonába.", "Az épületet soha nem alakították át, így megőrizte eredeti barokk formáját."],
      ro: ["Castelul a fost construit între anii 1654 și 1676.", "Sala de banchete a rămas nefinalizată din anul 1676.", "Colecția de arme conține piese rare din perioada Războiului de Treizeci de Ani.", "Clădirea a devenit muzeu de stat în anul 1967.", "Arhitectul principal a fost germanul Caspar Vogel.", "Castelul nu are sistem de încălzire, ceea ce a ajutat la conservarea inventarului."],
      en: ["The castle was constructed between 1654 and 1676.", "The banquet hall has remained unfinished since Wrangel's death in 1676.", "The armory is one of the largest private 17th-century collections in the world.", "The building was purchased by the Swedish state in 1967.", "The castle features over 50 rooms filled with period furniture and art.", "It is located on the Sko peninsula, an ancient site with Viking history."],
      es: ["Construido entre 1654 y 1676", "El gran salón no tiene techo hasta el día de hoy", "Contiene una armería de fama mundial", "El arquitecto fue el alemán Caspar Vogel"],
      pt: ["Construído entre 1654 e 1676", "O grande salão não possui teto até hoje", "Contém uma armaria de renome mundial", "O arquiteto foi o alemão Caspar Vogel"],
      fr: ["Construit entre 1654 et 1676", "La grande salle n'a toujours pas de plafond à ce jour", "Contient une armurerie de renommée mondiale", "L'architecte était l'Allemand Caspar Vogel"],
    },
    image: "/poi-images/sweden-skokloster-castle-history-v2.webp",
