imageHint: "Uppsala Cathedral twin towers",
    descriptionAdvanced: {
      de: "Der Dom zu Uppsala ist die größte und höchste Kirche in Skandinavien und dient als Sitz des Erzbischofs von Uppsala. Der Bau der gotischen Kathedrale begann um 1272 und dauerte über 150 Jahre bis zur Weihe im Jahr 1435. Die markanten Türme erreichen eine Höhe von 118,7 Metern und prägen die Skyline der Stadt. Jahrhundertelang war der Dom die Krönungsstätte der schwedischen Könige und ist bis heute die letzte Ruhestätte zahlreicher bedeutender Persönlichkeiten, darunter Gustav Wasa, Johan III. und der Naturforscher Carl von Linné. Während des großen Stadtbrandes von 1702 erlitt die Kathedrale schwere Schäden, wurde aber später umfassend restauriert, wobei im späten 19. Jahrhundert unter Helgo Zettervall der heutige neugotische Stil verstärkt wurde. Im Inneren beherbergt der Dom wertvolle Schätze, darunter den Schrein des heiligen Erik, des Schutzpatrons Schwedens. Als religiöses Zentrum und nationales Denkmal spielt die Kathedrale eine zentrale Rolle in der schwedischen Geschichte und Kultur.",
      hu: "Az uppsalai székesegyház Skandinávia legnagyobb és legmagasabb temploma, amely az Uppsalai főegyházmegye érseki székhelyeként szolgál. A gótikus katedrális építése 1272 körül kezdődött, és több mint 150 éven át tartott, mire 1435-ben felszentelték. Az épület ikertornyai 118,7 méter magasak, ami pontosan megegyezik a templom hosszával. Évszázadokon keresztül itt koronázták meg a svéd uralkodókat, és ez a végső nyughelye számos történelmi személyiségnek, köztük I. Gusztáv királynak, III. Jánosnak és a világhírű természettudósnak, Carl von Linnének. Az 1702-es nagy tűzvész jelentős károkat okozott az épületben, a 19. század végén pedig Helgo Zettervall vezetésével neogótikus stílusban építették újjá, ekkor nyerte el mai formáját. A templom belső terében őrzik Szent Eriknek, Svédország védőszentjének ereklyéit egy aranyozott ládában. A katedrális nemcsak vallási központ, hanem Svédország történelmi identitásának egyik legfontosabb szimbóluma is.",
      ro: "Catedrala din Uppsala este cel mai mare și cel mai înalt lăcaș de cult din Scandinavia, fiind sediul Arhiepiscopului de Uppsala. Construcția catedralei gotice a început în jurul anului 1272 și a durat mai bine de un secol și jumătate, fiind sfințită în 1435. Turnurile sale ating înălțimea de 118,7 metri, o dimensiune care corespunde simbolic lungimii navei bisericii. Timp de secole, catedrala a fost locul de încoronare al monarhilor suedezi și servește ca necropolă regală, adăpostind mormintele lui Gustav Vasa, Johan al III-lea și ale naturalistului Carl von Linné. După incendiul devastator din 1702, structura a suferit modificări importante, fiind restaurată extensiv în stil neogotic la sfârșitul secolului al XIX-lea sub îndrumarea lui Helgo Zettervall. În interiorul său se află racla aurită a Sfântului Erik, patronul spiritual al Suediei. Catedrala rămâne un simbol central al istoriei religioase și politice suedeze, fiind vizitată anual de mii de pelerini și turiști.",
      en: "Uppsala Cathedral is the largest and tallest church in Scandinavia, serving as the seat of the Archbishop of Uppsala. Construction of the Gothic cathedral began around 1272 and continued for over 150 years until its consecration in 1435. Its twin towers reach a height of 118.7 meters, a measurement that notably matches the church's total length. For centuries, the cathedral was the traditional coronation site for Swedish monarchs and remains the final resting place of several historical figures, including King Gustav Vasa, John III, and the world-renowned botanist Carl Linnaeus. The building suffered significant damage during the Great Fire of 1702, leading to major restorations, most notably the late 19th-century Neo-Gothic overhaul led by Helgo Zettervall. Inside, the cathedral houses the gilded shrine of Saint Erik, the patron saint of Sweden. As a national monument and religious center, the cathedral stands as a profound symbol of Swedish history and cultural identity.",
      es: "La Catedral de Uppsala es la catedral más grande de Escandinavia. Esta iglesia gótica de ladrillo ha servido durante siglos como lugar de coronación y entierro de los monarcas suecos.",
      pt: "A Catedral de Uppsala é a maior catedral da Escandinávia. Esta igreja gótica de tijolo serviu durante séculos como local de coroação e sepultamento de monarcas suecos.",
      fr: "La cathédrale d'Uppsala est la plus grande cathédrale de Scandinavie. Cette église gothique en brique a servi pendant des siècles de lieu de couronnement et de sépulture pour les monarques suédois.",
    },
    factsAdvanced: {
      de: ["Mit 118,7 Metern ist sie die höchste Kirche Skandinaviens.", "Der Bau dauerte von etwa 1272 bis 1435.", "In der Kathedrale befindet sich das Grab von Gustav Wasa (verstorben 1560).", "Der Schrein des Heiligen Erik wird seit dem 13. Jahrhundert hier aufbewahrt.", "Die Glocke 'Storan' ist mit 7 Tonnen die größte Kirchenglocke Schwedens.", "Die Kathedrale wurde nach dem Brand von 1702 im 19. Jahrhundert neugotisch umgestaltet."],
      hu: ["A templom magassága és hossza egyaránt 118,7 méter.", "Az építkezés 1272-ben kezdődött és 1435-ben fejeződött be.", "Itt található Carl von Linné, a modern rendszertan atyjának sírja.", "A katedrális 1702-ben majdnem teljesen leégett egy városi tűzvészben.", "A 'Storan' nevű harang 7300 kilogramm súlyú.", "A templom kincstára számos középkori textíliát és koronázási ékszert őriz."],
      ro: ["Înălțimea turnurilor este de 118,7 metri.", "Sfințirea oficială a avut loc în anul 1435.", "Gustav Vasa, fondatorul Suediei moderne, este înmormântat aici.", "Racla Sfântului Erik a fost donată în anul 1273.", "Restaurarea majoră din secolul al XIX-lea a durat între 1885 și 1893.", "Catedrala este situată în centrul istoric al orașului Uppsala, lângă universitate."],
      en: ["The cathedral's height of 118.7 meters equals its length.", "Construction began in 1272 and the church was consecrated in 1435.", "It houses the burial site of King Gustav Vasa and his three wives.", "The cathedral treasury contains one of Europe's finest collections of medieval textiles.", "The current towers were added during the Zettervall restoration in the 1880s.", "Archbishop Nathan Söderblom, a Nobel Peace Prize winner, is buried here."],
      es: ["La altura de las torres es exactamente de 118,7 metros", "La construcción duró de 1272 a 1435", "Lugar de entierro de Gustavo Vasa y Carlos Linneo", "El edificio eclesiástico más grande del norte de Europa"],
      pt: ["A altura das torres é exatamente 118,7 metros", "A construção durou de 1272 a 1435", "Local de sepultamento de Gustavo Vasa e Carl von Linné", "O maior edifício eclesiástico do norte da Europa"],
      fr: ["La hauteur des tours est exactement de 118,7 mètres", "La construction a duré de 1272 à 1435", "Lieu de sépulture de Gustave Vasa et Carl von Linné", "Le plus grand édifice religieux d'Europe du Nord"],
    },
