      ro: ["Lungimea formațiunii: 67 metri", "Datată în jurul anului 600 d.Hr.", "Formată din 59 de pietre de gresie mari", "Cea mai mare navă de piatră din Suedia"],
      en: ["Length of the formation: 67 meters", "Dated to approximately 600 AD", "Consists of 59 large sandstone blocks", "Largest ship setting in Sweden"],
      es: ["Longitud de la formación: 67 metros", "Datado aprox. en el 600 d.C.", "Consta de 59 grandes piedras areniscas", "El conjunto de piedras más grande de Suecia"],
      pt: ["Comprimento da formação: 67 metros", "Datado aprox. em 600 d.C.", "Composto por 59 grandes pedras de arenito", "Maior conjunto de pedras da Suécia"],
