imageHint: "Tjolöholm Castle Tudor architecture",
    descriptionAdvanced: {
      de: "Schloss Tjolöholm (Tjolöholms slott) in der Nähe von Kungsbacka ist eines der bemerkenswertesten Bauwerke Schwedens und ein herausragendes Beispiel für den Tudor-Stil des frühen 20. Jahrhunderts. Das Schloss wurde zwischen 1898 und 1904 für den Kaufmann James Fredrik Dickson und seine Frau Blanche erbaut. Der Entwurf stammt von dem Architekten Lars Israel Wahlman, der sich stark von der britischen Arts and Crafts-Bewegung inspirieren ließ. Das Gebäude beeindruckt durch seine detailreiche Fassade aus Granit und seine luxuriöse Innenausstattung, die modernsten Komfort mit traditionellem Handwerk verbindet. Tjolöholm war seiner Zeit weit voraus und verfügte über 28 Badezimmer, eine Zentralheizung und eine der ersten Staubsaugeranlagen der Welt. Die umliegende Parklandschaft wurde als englischer Garten gestaltet und unterstreicht den herrschaftlichen Charakter der Anlage. Nach dem frühen Tod der Besitzer wurde das Schloss 1971 von der Stadt Göteborg und der Gemeinde Kungsbacka erworben und der Öffentlichkeit zugänglich gemacht. Heute ist es ein beliebtes Ausflugsziel, das für seine Architektur, die historischen Gärten und kulturellen Veranstaltungen bekannt ist.",
      hu: "A Tjolöholm-kastély (Tjolöholms slott) Kungsbacka közelében található, és Svédország egyik legkülönlegesebb építészeti emléke. Az 1898 és 1904 között épült kastély a brit Tudor-stílus jegyeit ötvözi az Arts and Crafts mozgalom esztétikájával. A megrendelő a jómódú James Fredrik Dickson és felesége, Blanche volt, a terveket pedig Lars Israel Wahlman építész készítette. Az épület nemcsak külső megjelenésével, hanem technikai felszereltségével is korának élvonalába tartozott: 28 fürdőszobát alakítottak ki benne, központi fűtéssel és az ország egyik első porszívórendszerével szerelték fel. A belső terekben a finom fafaragások és az elegáns szövetek dominálnak, megidézve az angol úrilakok hangulatát. A kastélyt körülvevő parkot angol tájképi kertként alakították ki, amely harmonikusan illeszkedik a tengerparti tájba. 1971 óta a kastély nyilvános múzeumként és rendezvényközpontként működik, bemutatva a svéd arisztokrácia századfordulós luxusát és a modern kényelem iránti igényét.",
      ro: "Castelul Tjolöholm (Tjolöholms slott), situat în apropiere de Kungsbacka pe coasta de vest, este un exemplu remarcabil de arhitectură Tudor-revival și unul dintre cele mai neobișnuite castele din Suedia. Construit între 1898 și 1904 pentru bogatul comerciant James Fredrik Dickson și soția sa Blanche, edificiul a fost proiectat de arhitectul Lars Israel Wahlman în spiritul mișcării britanice Arts and Crafts. Castelul impresionează prin fațada sa elaborată din granit și interioarele opulente, fiind dotat la acea vreme cu tehnologii revoluționare pentru începutul secolului XX. Tjolöholm dispunea de 28 de băi, încălzire centrală și unul dintre primele sisteme de aspirare centralizată din lume. Grădinile înconjurătoare au fost concepute ca un parc englezesc vast, care coboară spre malul mării. În 1971, proprietatea a fost achiziționată de primăria din Göteborg și comuna Kungsbacka, fiind transformată într-un muzeu și centru cultural deschis publicului. Astăzi, Tjolöholm este faimos pentru autenticitatea sa istorică, expozițiile de artă și evenimentele anuale organizate în decorul său pitoresc.",
      en: "Tjolöholm Castle (Tjolöholms slott), located near Kungsbacka, is one of Sweden's most unique architectural landmarks, showcasing a grand Tudor-revival style rare in Scandinavia. Constructed between 1898 and 1904 for merchant James Fredrik Dickson and his wife Blanche, the castle was designed by architect Lars Israel Wahlman, heavily influenced by the British Arts and Crafts movement. The granite structure is renowned not only for its detailed craftsmanship but also for its advanced technological features for the time, such as 28 bathrooms, central heating, and a revolutionary built-in vacuum cleaning system. The interior is lavishly decorated with mahogany, marble, and intricate fabrics, mirroring the elegance of an English country estate. The castle is surrounded by a vast English-style garden and parkland that stretches toward the sea. Since 1971, it has been owned by the City of Gothenburg and the Kungsbacka municipality, functioning as a popular museum and cultural destination. Tjolöholm remains a testament to the luxury and innovative spirit of the Swedish upper class at the turn of the 20th century.",
      es: "El castillo de Tjolöholm es un ejemplo único del estilo Arts and Crafts en Suecia. Construido a principios del siglo XX, el castillo parece una mansión inglesa.",
      pt: "O Castelo de Tjolöholm é um exemplo único do estilo Arts and Crafts na Suécia. Construído no início do século XX, o castelo parece uma mansão inglesa.",
      fr: "Le château de Tjolöholm est un exemple unique du style Arts and Crafts en Suède. Construit au début du XXe siècle, le château ressemble à un manoir anglais.",
    },
    factsAdvanced: {
      de: ["Das Schloss wurde zwischen 1898 und 1904 erbaut.", "Es verfügt über 28 Badezimmer, was zur Bauzeit außergewöhnlich war.", "Lars Israel Wahlman entwarf das Gebäude im Tudor-Stil.", "Eines der ersten zentralen Staubsaugersysteme wurde hier installiert.", "Das Anwesen umfasst eine Fläche von etwa 1.000 Hektar.", "Das Schloss wurde 1971 für die Öffentlichkeit zugänglich gemacht."],
      hu: ["A kastély 1898 és 1904 között épült fel.", "Az épületben 28 modern fürdőszobát alakítottak ki.", "Tervezője, Lars Israel Wahlman az angol Tudor-stílust követte.", "Itt szerelték fel Svédország egyik legelső porszívórendszerét.", "A kastély kertjét az angol tájképi kertek mintájára tervezték.", "A területen egy különálló munkásfalu és templom is található."],
      ro: ["Construcția castelului a fost finalizată în anul 1904.", "Clădirea dispune de un număr impresionant de 28 de băi.", "Arhitectul Lars Israel Wahlman a fost cel care a proiectat edificiul.", "Castelul deține unul dintre primele aspiratoare din lume, de mărimea unei trăsuri.", "Proprietatea a fost vândută autorităților publice în 1971.", "Tjolöholm este un loc popular pentru filmări, inclusiv pentru filmul Melancholia."],
      en: ["The castle was constructed over a six-year period (1898–1904).", "It was built with 28 bathrooms, a rare luxury at the time.", "The design was inspired by English Tudor-style country houses.", "The castle featured a horse-drawn vacuum cleaner, one of the first of its kind.", "It has been a protected heritage site since 1991.", "The estate includes a unique workers' village designed in a matching style."],
      es: ["Construido entre 1898 y 1904", "Cuenta con un sistema de aspiración moderno para la época", "El arquitecto fue el sueco Lars Israel Wahlman", "Posee un jardín inspirado en el modelo británico"],
      pt: ["Construído entre 1898 e 1904", "Possui um sistema de aspiração moderno para a época", "O arquiteto foi o sueco Lars Israel Wahlman", "Possui um jardim inspirado no modelo britânico"],
      fr: ["Construit entre 1898 et 1904", "Dispose d'un système d'aspiration moderne pour l'époque", "L'architecte était le Suédois Lars Israel Wahlman", "Possède un jardin inspiré du modèle britannique"],
    },
    image: "/poi-images/sweden-tjoloholm-castle-history-v2.webp",
