    imageHint: "medieval stone ruins landscape",
    descriptionAdvanced: {
      de: "Die Ruinen der Abtei Skokloster (Sko kloster) stammen von einem Zisterzienserinnenkloster, das in den 1220er Jahren gegründet wurde. Es liegt am Ufer des Mälaren-Sees in Uppland und war eines der bedeutendsten geistlichen Zentren der Region im Mittelalter. Die heute noch sichtbare Skokloster-Kirche war ursprünglich Teil der Klosteranlage und wurde um 1230 im Backsteingotik-Stil errichtet. Während der Reformation unter König Gustav Wasa im 16. Jahrhundert wurde das Kloster säkularisiert und die Gebäude teilweise abgerissen oder dem Verfall preisgegeben. Die erhaltene Kirche dient heute als Gemeindekirche und beherbergt bedeutende Grabmäler sowie mittelalterliche Kunstschätze. In unmittelbarer Nähe zu den Ruinen und der Kirche befindet sich das berühmte Barockschloss Skokloster, das im 17. Jahrhundert von Carl Gustaf Wrangel erbaut wurde. Die Ruinen bieten einen faszinierenden Einblick in die monastische Geschichte Schwedens vor dem Übergang zum Protestantismus und sind ein wichtiges archäologisches Denkmal der Backsteinbaukunst.",
      hu: "A Skokloster apátság (Sko kloster) romjai egy ciszterci apácakolostor maradványai, amelyet az 1220-as években alapítottak. Az Uppland tartományban, a Mälaren-tó partján fekvő kolostor a középkorban a régió egyik legfontosabb szellemi és vallási központja volt. A ma is álló Skokloster-templom eredetileg a kolostorkomplexum része volt, és 1230 körül épült tégla-gótikus stílusban. A 16. századi reformáció idején, I. Gusztáv svéd király uralkodása alatt a kolostort szekularizálták, az épületek nagy részét lebontották vagy hagyták lepusztulni. A megmaradt templom ma plébániatemplomként működik, és értékes síremlékeket, valamint középkori műtárgyakat őriz. Közvetlenül a romok és a templom mellett található a híres barokk Skokloster-kastély, amelyet a 17. században építtetett Carl Gustaf Wrangel tábornagy. A romok különleges betekintést nyújtanak Svédország reformáció előtti szerzetesi múltjába és a középkori téglaépítészet korai szakaszába.",
      ro: "Ruinele abației Skokloster (Sko kloster) aparțin unei foste mănăstiri cisterciene de maici, fondată în anii 1220. Situată pe malul lacului Mälaren în Uppland, mănăstirea a fost unul dintre cele mai importante centre spirituale ale regiunii în perioada medievală. Biserica Skokloster, care este încă în picioare, a făcut parte inițial din complexul monastic și a fost construită în jurul anului 1230 în stil gotic din cărămidă. În timpul Reformei din secolul al XVI-lea, sub regele Gustav Vasa, mănăstirea a fost secularizată, iar clădirile sale au fost parțial demolate sau lăsate în paragină. Biserica supraviețuitoare servește astăzi ca biserică parohială și adăpostește morminte nobiliare importante și comori de artă medievală. În imediata vecinătate a ruinelor se află faimosul castel baroc Skokloster, construit în secolul al XVII-lea de Carl Gustaf Wrangel. Ruinele oferă o perspectivă fascinantă asupra istoriei monahale a Suediei înainte de tranziția la protestantism și reprezintă un monument arheologic semnificativ.",
      en: "The Skokloster Abbey ruins (Sko kloster) are the remains of a Cistercian nunnery founded in the 1220s. Located on the shores of Lake Mälaren in Uppland, the abbey served as a prominent spiritual and cultural center during the Middle Ages. The Skokloster Church, which still stands today, was originally part of the monastic complex and was constructed around 1230 in the Brick Gothic style. Following the Reformation in the 16th century under King Gustav Vasa, the monastery was secularized, leading to the gradual demolition or decay of most monastic buildings. The surviving church now serves as a parish church and contains significant noble monuments and medieval artifacts. Adjacent to the ruins and the church is the world-renowned Baroque Skokloster Castle, built in the 17th century by Field Marshal Carl Gustaf Wrangel. The ruins provide a valuable glimpse into Sweden's pre-Reformation monastic life and stand as an important archaeological example of early brick architecture in the region.",
      es: "Las ruinas del antiguo monasterio cisterciense del siglo XIII muestran los restos de arquitectura sacra, que alguna vez formó un importante centro religioso a orillas del lago Mälaren.",
      pt: "As ruínas do antigo mosteiro cisterciense do século XIII mostram os restos de arquitetura sacra, que outrora formou um importante centro religioso às margens do lago Mälaren.",
      fr: "Les ruines de l'ancien monastère cistercien du XIIIe siècle présentent les vestiges d'une architecture sacrée, qui formait autrefois un important centre religieux au bord du lac Mälaren.",
    },
    factsAdvanced: {
      de: ["Das Kloster wurde um 1225 als Cistercienserinnen-Abtei gegründet.", "Die Skokloster-Kirche ist eine der ältesten Backsteinkirchen in Schweden.", "Nach der Reformation im Jahr 1527 fiel der Klosterbesitz an die schwedische Krone.", "Die Kirche beherbergt die Grabstätte der Familie Wrangel aus dem 17. Jahrhundert.", "Archäologische Grabungen haben Reste des Kreuzgangs und der Zellen freigelegt.", "Das Klostergelände liegt direkt am See Mälaren, einem wichtigen Handelsweg."],
      hu: ["A kolostort 1225 körül alapították ciszterci apácák számára.", "A Skokloster-templom Svédország egyik legrégebbi téglaépítésű temploma.", "1527-ben, a reformációt követően az épületek a svéd korona tulajdonába kerültek.", "A templomban található a híres Wrangel család 17. századi kriptája.", "A régészeti feltárások során megtalálták a kerengő és a szerzetesi cellák alapjait.", "A terület a Mälaren-tó partján fekszik, amely a középkorban kulcsfontosságú útvonal volt."],
      ro: ["Mănăstirea a fost fondată în jurul anului 1225 pentru călugărițele cisterciene.", "Biserica Skokloster este una dintre cele mai vechi biserici de cărămidă din Suedia.", "În 1527, după Reformă, proprietățile mănăstirii au fost confiscate de coroana suedeză.", "Biserica adăpostește cripta familiei Wrangel, datând din secolul al XVII-lea.", "Săpăturile arheologice au scos la iveală resturi ale claustrului și ale chiliilor.", "Situl mănăstirii este situat pe malul lacului Mälaren, o rută comercială istorică."],
      en: ["The monastery was founded around 1225 for Cistercian nuns.", "The Skokloster Church is one of the earliest brick-built churches in Sweden.", "Following the Reformation in 1527, the abbey's lands were seized by the Crown.", "The church houses the 17th-century burial chapel of the noble Wrangel family.", "Archaeological excavations have identified the foundations of the cloister and cells.", "The site is positioned on the shores of Lake Mälaren, a vital historic waterway."],
      es: ["Fundado alrededor de 1230", "Orden del Císter", "Cerca del castillo de Skokloster", "Secularizado en 1527", "Potentes muros de piedra de campo", "Ubicación en la orilla del Mälaren"],
      pt: ["Fundado por volta de 1230", "Ordem de Cister", "Perto do castelo de Skokloster", "Secularizado em 1527", "Poderosas paredes de pedra de campo", "Localização na margem do Mälaren"],
      fr: ["Fondé vers 1230", "Ordre cistercien", "Près du château de Skokloster", "Sécularisé en 1527", "Murs massifs en pierre des champs", "Situation au bord du lac Mälaren"],
    },
