      es: ["Época vikinga (800-1050)", "Escritura rúnica", "Protección de monumentos", "Inscripciones históricas"],
      pt: ["Era viking (800-1050)", "Escrita rúnica", "Proteção de monumentos", "Inscrições históricas"],
      fr: ["Ère viking (800-1050)", "Écriture runique", "Protection des monuments", "Inscriptions historiques"],
