      de: "Ein Beispiel mittelalterlicher Kirchenarchitektur in Schonen. Das Gebäude bewahrt bedeutende Fresken aus dem 15. Jahrhundert.",
      hu: "Középkori templomépítészet példája Skånéban. Az épület jelentős 15. századi freskókat őriz.",
      ro: "Un exemplu de arhitectură bisericească medievală în Skåne. Clădirea păstrează fresce importante din secolul al XV-lea.",
