      hu: ["Épült 1872-ben", "Neogótikus stílus", "Építész: Albert Törnqvist", "Egy középkori templomot váltott fel"],
      ro: ["Construită în 1872", "Stil neogotic", "Arhitect: Albert Törnqvist", "A înlocuit o biserică medievală"],
      en: ["Built in 1872", "Neo-Gothic style", "Architect: Albert Törnqvist", "Replaced a medieval church"],
      es: ["Construida en 1872", "Estilo neogótico", "Arquitecto: Albert Törnqvist", "Reemplazó a una iglesia medieval"],
      pt: ["Construída em 1872", "Estilo neogótico", "Arquiteto: Albert Törnqvist", "Substituiu uma igreja medieval"],
