      pt: "Uma enorme fortaleza junto ao lago Vättern, concebida no século XIX como a 'capital de reserva' da Suécia.",
      fr: "Une immense forteresse au bord du lac Vättern, conçue au XIXe siècle comme la 'capitale de réserve' de la Suède.",
