      pt: ["Construído no século XVI", "Residência da família Ehrenborg", "Marcas de bala de 1678", "Monumento nacional desde 1947", "Sistema de fosso", "Localizado perto de Hässleholm"],
      fr: ["Construit au XVIe siècle", "Résidence de la famille Ehrenborg", "Impacts de balles de 1678", "Monument national depuis 1947", "Système de douves", "Situé près de Hässleholm"],
