      es: ["Centro comercial de la época vikinga", "Patrimonio de la Humanidad por la UNESCO", "Excavaciones arqueológicas", "Museo disponible"],
      pt: ["Centro comercial da era viquingue", "Património Mundial da UNESCO", "Escavações arqueológicas", "Museu disponível"],
