    imageHint: "palace facade garden",
    descriptionAdvanced: {
      de: "Schloss Rosersberg, eines der zehn königlichen Schlösser Schwedens, liegt in einer malerischen Bucht des Mälaren-Sees nördlich von Stockholm. Es wurde in den 1630er Jahren von der Familie Oxenstierna im Stil der Renaissance erbaut, erhielt aber sein heutiges Aussehen durch umfangreiche Umbauten im späten 18. und frühen 19. Jahrhundert. Besonders bemerkenswert ist, dass Rosersberg das einzige königliche Schloss ist, das seine Inneneinrichtung aus der Zeit Karls XIV. Johann und der Königin Desideria fast vollständig bewahrt hat. Die Räume sind ein herausragendes Beispiel für den schwedischen Empire-Stil, auch Karl-Johann-Stil genannt, mit prächtigen Seidentapeten, vergoldeten Möbeln und kunstvollen Stuckarbeiten. Seit dem Tod von Königin Desideria im Jahr 1860 wurde das Schloss kaum noch als Residenz genutzt, was zur Konservierung des ursprünglichen Zustands beitrug. Lange Zeit beherbergte es die Infanterieschule der schwedischen Armee, bevor es vollständig als Museum und Veranstaltungsort zugänglich gemacht wurde. Der weitläufige Schlossgarten mit seinen barocken Alleen und dem englischen Landschaftspark lädt zu Spaziergängen ein.",
      hu: "A Rosersberg-palota, Svédország tíz királyi kastélyának egyike, a Mälaren-tó egyik festői öblében fekszik Stockholmtól északra. Az 1630-as években építtette az Oxenstierna család reneszánsz stílusban, de mai arculatát a 18. század végi és 19. század eleji átépítések során nyerte el. Rosersberg különlegessége, hogy ez az egyetlen királyi kastély, amely szinte teljesen érintetlenül megőrizte XIV. Károly János és Desideria királyné korából származó belső berendezését. A szobák a svéd empire stílus (más néven Károly János-stílus) kiemelkedő példái, pazar selyemtapétákkal, aranyozott bútorokkal és művészi stukkókkal. Desideria királyné 1860-as halála óta a kastélyt alig használták rezidenciaként, ami hozzájárult az eredeti állapot megmaradásához. Hosszú ideig a svéd hadsereg gyalogsági iskolájának adott otthont, mielőtt teljesen látogatható múzeummá és rendezvényhelyszínné vált volna. A kastélyt körülvevő kiterjedt kert barokk alléival és angolparkjával ideális helyszín a kikapcsolódásra.",
      ro: "Palatul Rosersberg, unul dintre cele zece castele regale ale Suediei, este situat într-un golf pitoresc al lacului Mälaren, la nord de Stockholm. A fost construit în anii 1630 de familia Oxenstierna în stil renascentist, dar și-a căpătat aspectul actual în urma unor renovări majore la sfârșitul secolului al XVIII-lea și începutul secolului al XIX-lea. Rosersberg este unic prin faptul că este singurul palat regal care și-a păstrat aproape integral interioarele din perioada regelui Carol al XIV-lea Ioan și a reginei Désirée. Camerele reprezintă un exemplu remarcabil al stilului Empire suedez, cunoscut și sub numele de stilul Carol Ioan, cu tapet de mătase somptuos, mobilier aurit și stucaturi elaborate. După moartea reginei Désirée în 1860, palatul a fost rar folosit ca reședință, ceea ce a ajutat la conservarea stării sale originale. Timp de mulți ani, a găzduit școala de infanterie a armatei suedeze înainte de a deveni muzeu. Grădinile vaste ale palatului, cu alei baroce și un parc peisagistic în stil englezesc, oferă un cadru istoric deosebit.",
      en: "Rosersberg Palace, one of Sweden's ten royal palaces, is situated in a scenic bay of Lake Mälaren north of Stockholm. Built in the 1630s by the Oxenstierna family in Renaissance style, it acquired its present appearance through extensive renovations in the late 18th and early 19th centuries. Rosersberg is unique as it is the only royal palace that has almost entirely preserved its interiors from the era of King Charles XIV John and Queen Desideria. The rooms are an outstanding example of the Swedish Empire style, also known as the Karl Johan style, featuring lavish silk wallpapers, gilded furniture, and intricate stucco work. Since the death of Queen Desideria in 1860, the palace has rarely been used as a residence, which has contributed to the preservation of its original state. For a long period, it housed the Swedish Army's Infantry School before being fully opened to the public as a museum and event venue. The extensive palace grounds, with baroque avenues and an English landscape park, provide a serene historical environment.",
      es: "El castillo de Rosersberg es uno de los castillos reales mejor conservados de la época de Carlos XIV Juan y exhibe magníficos interiores en estilo imperio sueco.",
      pt: "O castelo de Rosersberg é um dos castelos reais mais bem preservados da época de Carlos XIV João e exibe magníficos interiores em estilo império sueco.",
      fr: "Le château de Rosersberg est l'un des châteaux royaux les mieux préservés de l'époque de Charles XIV Jean et présente de magnifiques intérieurs de style Empire suédois.",
    },
    factsAdvanced: {
      de: ["Das Schloss wurde zwischen 1634 und 1638 von Gabriel Oxenstierna erbaut.", "Es wurde 1762 von der schwedischen Krone als Prinzenresidenz erworben.", "Die Inneneinrichtung ist seit den 1860er Jahren nahezu unverändert.", "Von 1874 bis 1961 wurde das Schloss militärisch als Schule genutzt.", "Karl XIV. Johann war der erste König aus dem Hause Bernadotte, der hier lebte.", "Die Schlosskapelle wurde im späten 17. Jahrhundert von Nicodemus Tessin d.J. gestaltet."],
      hu: ["A kastélyt 1634 és 1638 között építtette Gabriel Oxenstierna.", "1762-ben került a svéd korona tulajdonába hercegi rezidenciaként.", "A belső berendezés az 1860-as évek óta szinte változatlan maradt.", "1874 és 1961 között az épület katonai gyalogsági iskolaként működött.", "XIV. Károly János volt az első Bernadotte-házi király, aki itt lakott.", "A palotakápolnát a 17. század végén ifjabb Nicodemus Tessin tervezte."],
      ro: ["Palatul a fost construit între 1634 și 1638 de către Gabriel Oxenstierna.", "A fost achiziționat de coroana suedeză în 1762 ca reședință princiară.", "Interioarele au rămas practic neschimbate din anii 1860.", "Între 1874 și 1961, palatul a fost folosit ca școală militară de infanterie.", "Carol al XIV-lea Ioan a fost primul rege din casa Bernadotte care a locuit aici.", "Capela palatului a fost decorată la sfârșitul secolului al XVII-lea de Nicodemus Tessin cel Tânăr."],
      en: ["The palace was built between 1634 and 1638 by Gabriel Oxenstierna.", "It was acquired by the Swedish Crown in 1762 as a princely residence.", "The interior decoration has remained largely unchanged since the 1860s.", "From 1874 to 1961, the palace was used as a military infantry school.", "Charles XIV John was the first Bernadotte king to reside at the palace.", "The palace chapel was redesigned in the late 17th century by Nicodemus Tessin the Younger."],
      es: ["Construido a partir de 1630", "Familia Oxenstierna", "Residencia real desde 1762", "Mobiliario original imperio", "Parque del castillo en el Mälaren", "Dormitorio Bernadotte"],
      pt: ["Construído a partir de 1630", "Família Oxenstierna", "Residência real desde 1762", "Mobiliário original império", "Parque do castelo no Mälaren", "Quarto Bernadotte"],
      fr: ["Construit à partir de 1630", "Famille Oxenstierna", "Résidence royale depuis 1762", "Mobilier original de style Empire", "Parc du château sur le lac Mälaren", "Chambre à coucher Bernadotte"],
    },
