    imageHint: "coastal stone fortress",
    descriptionAdvanced: {
      de: "Das Kastell von Karlshamn, gelegen auf der Insel Frisholmen im Hafen der Stadt, war ein strategischer Eckpfeiler der schwedischen Verteidigung im 17. Jahrhundert. Nach dem Frieden von Roskilde im Jahr 1658, als Blekinge schwedisch wurde, ordnete König Karl X. Gustav den Bau der Befestigung an, um den neuen wichtigen Hafen zu schützen. Die Arbeiten begannen 1675 und das Kastell spielte eine entscheidende Rolle im Nordischen Krieg, als es mehrfach von dänischen Truppen angegriffen wurde. Die Architektur ist durch dicke Steinmauern, Bastionen und ein markantes Kommandantenhaus geprägt. Über die Jahrhunderte diente das Kastell nicht nur der Verteidigung, sondern auch als Gefängnis und Quarantänestation während Epidemien. Im 19. Jahrhundert verlor es seine militärische Bedeutung und wurde schließlich 1865 offiziell als Festung aufgelassen. Heute ist Frisholmen ein beliebtes Ziel für Bootsausflüge, wobei die gut erhaltenen Ruinen und Gebäude als Freilichtmuseum dienen und die bewegte Militärgeschichte der Region lebendig halten.",
      hu: "A Karlshamni erőd (Kastellet), amely a város kikötőjében található Frisholmen-szigeten fekszik, a 17. századi svéd védelem egyik stratégiai sarokköve volt. Az 1658-as roskildei béke után, amikor Blekinge tartomány svéd kézre került, X. Károly Gusztáv király elrendelte az erődítmény megépítését az új, fontos kikötő védelmére. A munkálatok 1675-ben kezdődtek, és az erőd döntő szerepet játszott az északi háborúban, amikor a dán csapatok többször is megtámadták. Építészetét vastag kőfalak, bástyák és egy jellegzetes parancsnoki épület jellemzi. Az évszázadok során az erőd nemcsak védelmi célokat szolgált, hanem börtönként és karanténállomásként is működött a járványok idején. A 19. században elvesztette katonai jelentőségét, és 1865-ben hivatalosan is leszerelték. Napjainkban Frisholmen népszerű kirándulóhely, ahol a jól megőrzött romok és épületek szabadtéri múzeumként mutatják be a régió mozgalmas katonai múltját.",
      ro: "Fortăreața Karlshamn, cunoscută sub numele de Kastellet și situată pe insula Frisholmen în portul orașului, a fost un punct strategic esențial al apărării suedeze în secolul al XVII-lea. După Pacea de la Roskilde din 1658, când provincia Blekinge a devenit suedeză, regele Carol al X-lea Gustav a ordonat construcția fortificației pentru a proteja noul port important. Lucrările au început în 1675, iar fortăreața a jucat un rol crucial în Războiul Nordului, fiind atacată de mai multe ori de trupele daneze. Arhitectura sa se caracterizează prin ziduri groase de piatră, bastioane și o casă distinctivă a comandantului. De-a lungul secolelor, fortăreața nu a servit doar pentru apărare, ci și ca închisoare și stație de carantină în timpul epidemiilor. În secolul al XIX-lea, și-a pierdut importanța militară și a fost dezafectată oficial în 1865. Astăzi, insula Frisholmen este o destinație populară pentru excursii cu barca, ruinele și clădirile bine conservate servind drept muzeu în aer liber care păstrează vie istoria militară a regiunii.",
      en: "Karlshamn Fortress, known as Kastellet and located on Frisholmen island in the city's harbor, was a strategic cornerstone of Swedish defense in the 17th century. Following the Treaty of Roskilde in 1658, which brought the province of Blekinge under Swedish rule, King Charles X Gustav ordered the construction of the fortification to protect the vital new port. Work began in 1675, and the fortress played a decisive role during the Scanian War and the Great Northern War, facing multiple attacks by Danish forces. Its architecture features thick stone walls, bastions, and a prominent commander's house. Over the centuries, the fort served not only as a military defense point but also as a prison and a quarantine station during epidemics. In the 19th century, it lost its military significance and was officially decommissioned in 1865. Today, Frisholmen is a popular destination for boat trips, with its well-preserved ruins and buildings serving as an open-air museum that brings the region's turbulent military history to life.",
      es: "La fortaleza insular 'Kastellet' frente a Karlshamn fue construida en el siglo XVII para proteger el estratégicamente importante puerto y para controlar las aguas del mar Báltico.",
      pt: "A fortaleza insular 'Kastellet', frente a Karlshamn, foi construída no século XVII para proteger o estrategicamente importante porto e para controlar as águas do mar Báltico.",
      fr: "La forteresse insulaire 'Kastellet', face à Karlshamn, a été construite au XVIIe siècle pour protéger le port stratégiquement important et pour contrôler les eaux de la mer Baltique.",
    },
    factsAdvanced: {
      de: ["Der Bau des Kastells wurde 1675 auf Befehl von Karl X. Gustav begonnen.", "Die Festung wurde auf der kleinen Insel Frisholmen errichtet.", "Im Jahr 1676 wurde das Kastell kurzzeitig von den Dänen erobert.", "Es diente im 18. Jahrhundert als Quarantänestation für die Pest.", "Die offizielle Stilllegung der militärischen Anlage erfolgte 1865.", "Das heutige Kommandantenhaus stammt aus den 1750er Jahren."],
      hu: ["Az erőd építése 1675-ben kezdődött X. Károly Gusztáv parancsára.", "Az erődítmény a Frisholmen nevű kis szigeten épült fel.", "1676-ban a dánok rövid időre elfoglalták az erődöt.", "A 18. században pestiskaranténként is használták a szigetet.", "A katonai létesítményt hivatalosan 1865-ben zárták be.", "A ma látható parancsnoki ház az 1750-es évekből származik."],
      ro: ["Construcția fortului a început în 1675 la ordinul lui Carol al X-lea Gustav.", "Fortificația a fost ridicată pe mica insulă numită Frisholmen.", "În anul 1676, fortul a fost cucerit pentru scurt timp de către danezi.", "În secolul al XVIII-lea, a servit drept stație de carantină pentru ciumă.", "Dezafectarea oficială a facilității militare a avut loc în anul 1865.", "Casa comandantului, vizibilă astăzi, datează din anii 1750."],
      en: ["Construction of the fort began in 1675 on the orders of Charles X Gustav.", "The fortification was built on the small island of Frisholmen.", "In 1676, the fort was briefly captured by Danish forces.", "It served as a plague quarantine station during the 18th century.", "The military facility was officially decommissioned in 1865.", "The current commander's house dates back to the 1750s."],
      es: ["Construido entre 1675-1700", "Isla de Frisholmen", "Diseño de Erik Dahlbergh", "Uso en la Guerra del Norte", "Polvorín conservado", "Hoy teatro al aire libre"],
      pt: ["Construído entre 1675-1700", "Ilha de Frisholmen", "Design de Erik Dahlbergh", "Uso na Guerra do Norte", "Pólvora preservada", "Hoje teatro ao ar livre"],
      fr: ["Construit entre 1675-1700", "Île de Frisholmen", "Conception d'Erik Dahlbergh", "Utilisé pendant la Grande Guerre du Nord", "Poudrière préservée", "Aujourd'hui théâtre en plein air"],
    },
