    imageHint: "historic building facade",
    descriptionAdvanced: {
      de: "Die Arvika Kunsthalle ist in einem der markantesten Gebäude der Stadt untergebracht, einem ehemaligen Bankgebäude aus dem Jahr 1903. Die Architektur des Gebäudes ist durch den Jugendstil geprägt und spiegelt den wirtschaftlichen Aufschwung Arvikas zu Beginn des 20. Jahrhunderts wider. Die Kunsthalle dient als wichtiges Zentrum für zeitgenössische Kunst und regionales Handwerk, wobei ein besonderer Fokus auf dem Erbe der Rackstad-Künstlerkolonie liegt. Diese Kolonie, die Ende des 19. Jahrhunderts gegründet wurde, machte Arvika zu einem bedeutenden Treffpunkt für schwedische Maler und Kunsthandwerker. Die Ausstellungen in der Kunsthalle wechseln regelmäßig und zeigen Werke lokaler Künstler sowie nationale und internationale Positionen. Neben den Ausstellungsflächen bietet die Institution auch Programme zur Kunstvermittlung und kulturelle Veranstaltungen an. Die Erhaltung des historischen Ambientes der ehemaligen Bankräumlichkeiten verleiht den Kunstpräsentationen eine einzigartige Atmosphäre und dokumentiert die städtische Entwicklungsgeschichte.",
      hu: "Az Arvika Műcsarnok (Arvika Konsthall) a város egyik legimpozánsabb épületében, egy 1903-ban emelt egykori banképületben kapott helyet. Az épület építészete a szecesszió (Jugendstil) jegyeit viseli magán, tükrözve Arvika 20. század eleji gazdasági fellendülését. A műcsarnok a kortárs képzőművészet és a regionális kézművesség egyik legfontosabb központja, különös tekintettel a híres Rackstad művésztelep örökségére. Ez a művészközösség, amely a 19. század végén jött létre, Arvikát a svéd festők és iparművészek egyik meghatározó találkozóhelyévé tette. A műcsarnok kiállításai rendszeresen cserélődnek, bemutatva a helyi alkotók munkái mellett országos és nemzetközi művészek tárlatait is. A kiállítóterek mellett az intézmény művészeti oktatási programokat és kulturális eseményeket is szervez. Az egykori banktermek történelmi hangulatának megőrzése egyedi hátteret biztosít a műalkotásoknak, miközben dokumentálja a városfejlesztés történetét.",
      ro: "Galeria de Artă din Arvika (Arvika Konsthall) este găzduită într-una dintre cele mai remarcabile clădiri ale orașului, un fost sediu bancar construit în anul 1903. Arhitectura edificiului este puternic influențată de stilul Art Nouveau (Jugendstil), reflectând prosperitatea economică a orașului Arvika de la începutul secolului XX. Galeria funcționează ca un centru vital pentru arta contemporană și meșteșugurile regionale, având un accent deosebit pe moștenirea coloniei de artiști Rackstad. Această colonie, fondată la sfârșitul secolului al XIX-lea, a transformat Arvika într-un loc de întâlnire esențial pentru pictorii și artizanii suedezi de renume. Expozițiile din cadrul galeriei sunt temporare și variate, prezentând atât lucrări ale artiștilor locali, cât și perspective naționale și internaționale. Pe lângă spațiile expoziționale, instituția oferă programe de educație artistică și organizează evenimente culturale. Conservarea ambianței istorice a vechii bănci oferă o atmosferă unică prezentărilor de artă și documentează istoria dezvoltării urbane.",
      en: "Arvika Art Hall is housed in one of the city's most distinctive buildings, a former bank constructed in 1903. The architecture of the building is characterized by the Art Nouveau (Jugendstil) style, reflecting the economic prosperity of Arvika at the beginning of the 20th century. The art hall serves as an important center for contemporary art and regional crafts, with a specific focus on the legacy of the Rackstad Artist Colony. This colony, established in the late 19th century, made Arvika a significant meeting point for Swedish painters and craftsmen. Exhibitions at the Art Hall change regularly, featuring works by local artists alongside national and international pieces. In addition to exhibition spaces, the institution offers art education programs and cultural events. The preservation of the historic bank interior provides a unique atmosphere for art displays and stands as a testament to the town's urban and cultural development.",
      es: "La Arvika Art Hall es una galería de arte en la ciudad de Arvika, en la provincia de Värmland. Fue construida en 1915 como sede de la asociación de artistas de Värmland. El edificio es un ejemplo destacado del estilo nacional romántico con elementos del Art Nouveau. La sala exhibe exposiciones temporales de arte contemporáneo y obras de artistas locales. Es especialmente conocida por su colección de la Escuela Rackstad, un grupo artístico en torno a Gustaf Fjæstad y Björn Ahlgrensson. La Arvika Art Hall es un centro cultural en la región y también organiza conciertos y conferencias.",
      pt: "A Arvika Art Hall é uma galeria de arte na cidade de Arvika, na província de Värmland. Foi construída em 1915 como sede da associação de artistas de Värmland. O edifício é um exemplo notável do estilo romântico nacional com elementos do Art Nouveau. A galeria exibe exposições temporárias de arte contemporânea e obras de artistas locais. É especialmente conhecida pela sua coleção da Escola Rackstad, um grupo artístico em torno de Gustaf Fjæstad e Björn Ahlgrensson. A Arvika Art Hall é um centro cultural na região e também organiza concertos e conferências.",
      fr: "L'Arvika Art Hall est une galerie d'art située dans la ville d'Arvika, dans la province de Värmland. Elle a été construite en 1915 comme siège de l'association des artistes de Värmland. Le bâtiment est un exemple remarquable du style romantique national avec des éléments Art Nouveau. La salle présente des expositions temporaires d'art contemporain et des œuvres d'artistes locaux. Elle est particulièrement connue pour sa collection de l'École de Rackstad, un groupe d'artistes autour de Gustaf Fjæstad et Björn Ahlgrensson. L'Arvika Art Hall est un centre culturel de la région qui organise également des concerts et des conférences.",
    },
